/**
 * @returns {string}
 */
async _getPasswordWithoutUI() {
  const serverURI = this._getServerURISpec();
  const logins = await Services.logins.searchLoginsAsync({
    origin: serverURI,
    httpRealm: serverURI,
  });
  for (const login of logins) {
    if (login.username == this.username) {
      return login.password;
    }
  }
  return null;
}
